panicEcoMetric('Plata que entró',$current['Pesos'],'Pesos reales que pagaron los jugadores por recargas.',['icon'=>'money','prefix'=>'$ ','flow'=>'in','comparison'=>panicEcoComparison($current['Pesos'],$previous['Pesos'],$period)]);
